import{_ as t,o,c as r,a2 as d}from"./chunks/framework.eFe5Lsvn.js";const g=JSON.parse('{"title":"Tuning the follower","description":"","frontmatter":{},"headers":[],"relativePath":"lib/tuning.md","filePath":"lib/tuning.md"}'),a={name:"lib/tuning.md"};function i(n,e,l,c,s,h){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="tuning-the-follower" tabindex="-1">Tuning the follower <a class="header-anchor" href="#tuning-the-follower" aria-label="Permalink to &quot;Tuning the follower&quot;">​</a></h1><h2 id="followerconfig" tabindex="-1"><code>FollowerConfig</code> <a class="header-anchor" href="#followerconfig" aria-label="Permalink to &quot;`FollowerConfig`&quot;">​</a></h2><p>Pass it with <code>withFollowerConfig(...)</code>. Fields are public, or use the <code>with*</code> helpers.</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>translationKp</code></td><td>6.0 (m/s)/m</td><td>Position feedback.</td></tr><tr><td><code>translationKv</code></td><td>0</td><td>Optional velocity-error feedback.</td></tr><tr><td><code>rotationKp</code></td><td>5.0 (rad/s)/rad</td><td>Heading feedback.</td></tr><tr><td><code>maxFeedbackVelocity</code> / <code>maxFeedbackOmega</code></td><td>1.5 m/s / 3.0 rad/s</td><td>Clamp on the feedback part only.</td></tr><tr><td><code>maxVelocity</code> / <code>maxOmega</code></td><td>5.0 m/s / 12 rad/s</td><td>Clamp on the total command.</td></tr><tr><td><code>useForceFeedforward</code></td><td>true</td><td>Sends the trajectory&#39;s module forces.</td></tr><tr><td><code>modules</code></td><td>4</td><td>Number of swerve modules.</td></tr></tbody></table><h2 id="tune-in-this-order" tabindex="-1">Tune in this order <a class="header-anchor" href="#tune-in-this-order" aria-label="Permalink to &quot;Tune in this order&quot;">​</a></h2><ol><li><strong>Drivetrain first.</strong> Tune the drive-motor velocity gains (kS, kV, kP) and steer gains with SysId. These are in the Tuner X project, and <code>CommandSwerveDrivetrain</code> has SysId bindings. No path follower can make up for a slow velocity loop.</li><li><strong>Check the model.</strong> Robot mass, MOI, wheel radius, and max speed in the Mayhem app must match the real robot. If they don&#39;t, the feedforward and force feedforward will be wrong.</li><li><strong>Feedforward only.</strong> Set <code>translationKp</code> and <code>rotationKp</code> to 0 and run a path. The robot should end up close to the target, within about 10–20 cm. If it overshoots during acceleration phases, compare runs with <code>withForceFeedforward(false)</code>. The force feedforward depends on accurate motor and gearing constants in <code>TunerConstants</code>.</li><li><strong>Feedback.</strong> Raise <code>translationKp</code> until tracking is tight without oscillation. Typical values are 4–10. Then raise <code>rotationKp</code> (typically 3–8).</li><li><strong>Recovery thresholds.</strong> Watch <code>/Mayhem/positionError</code> during clean runs. Keep <code>dilationStartError</code> above your normal tracking error. Keep <code>bridgeTriggerError</code> well above your worst clean-run error, or bridges will trigger without a real hit. See <a href="/Mayhem/lib/recovery">Bump recovery</a>.</li><li><strong>Accelerometer.</strong> Log the Pigeon&#39;s horizontal g during hard accelerations. If <code>accelSpikeG</code> false-triggers, raise it, or disable the spike check with <code>withAccelerometer(() -&gt; Double.NaN)</code>. Sustained-error detection still works without it.</li></ol>',6)])])}const f=t(a,[["render",i]]);export{g as __pageData,f as default};
